export function fetchBytes(r     )      {
    return (r.ok ? r.arrayBuffer() : Promise.reject(("" + "HTTP " + r.status + " for " + r.url)));
}

export function compileWasm(bytes     )      {
    return WebAssembly.compile(bytes);
}

export function fetchModule(url        )      {
    return fetch(url).then(fetchBytes).then(compileWasm);
}

